for (const p of projections)
  if (p.table === 'provider_connections' && (p.deleted || p.values[2] === 0)) {
    markRestoredCredentialRevoked(directory, String(p.keys[0]))
    database
      .prepare('UPDATE provider_connections SET has_persistent_credential=0 WHERE id=?')
      .run(...p.keys)
  }

for (const p of projections)
  if (p.table === 'provider_connections') {
    const restored = database.prepare('SELECT version FROM provider_connections WHERE id=?').get(...p.keys)
    // A later connection/credential generation cannot authorize a blob copied from an older one.
    // Conservatively require a new Key when the backup generation cannot be confirmed current.
    if (p.deleted || p.values[2] === 0 || (restored && Number(restored.version) < Number(p.values[0]))) {
      markRestoredCredentialRevoked(directory, String(p.keys[0]))
      database
        .prepare('UPDATE provider_connections SET has_persistent_credential=0 WHERE id=?')
        .run(...p.keys)
    }
    database.prepare('UPDATE provider_connections SET version=max(version,?) WHERE id=?').run(Number(p.values[0]), ...p.keys)
  }
